    # BÀI 9: Quản lí Tài chính Nhỏ: Chi tiêu Thông minh và Thói quen Tiết kiệm
    lessons.append(make_lesson(
        'lssong5-c3', 'lssong5-b09', 'Bài 9. Quản lí Tài chính Nhỏ: Chi tiêu Thông minh và Thói quen Tiết kiệm', 9,
        'Hình thành tư duy tài chính cá nhân căn bản tuổi Lớp 5: phân biệt rõ giữa "Cần" (Nhu cầu thiết yếu) và "Muốn" (Mong muốn nhất thời), thực hành quy tắc 3 chiếc lọ/hũ tiền (Tiết kiệm – Chi tiêu – Sẻ chia) và chống mua sắm bốc đồng',
        ['Phân biệt rạch ròi giữa thứ mình CẦN và thứ mình MUỐN', 'Áp dụng mô hình 3 hũ tài chính nhỏ: Tích lũy – Chi tiêu hợp lí – Sẻ chia yêu thương', 'Hiểu giá trị sức lao động của cha mẹ và thói quen "Chờ 48 giờ" trước khi mua món đắt'],
        [
            _q(9, 1, 'basic', 'Trong giáo dục tài chính cá nhân cho học sinh tiểu học, sự khác nhau cơ bản nhất giữa "Thứ mình CẦN (Needs)" và "Thứ mình MUỐN (Wants)" là gì?',
               '"Cần" là những đồ thiết yếu phục vụ học tập, sức khỏe sinh hoạt hằng ngày; còn "Muốn" là thứ có thêm cho vui mắt nhưng không có vẫn sống và học tốt bình thường',
               ['"Cần" luôn là đồ chơi đắt tiền nhất trong siêu thị, còn "Muốn" là cơm ăn hằng ngày', 'Hai khái niệm này hoàn toàn giống hệt nhau không có điểm gì khác biệt', '"Cần" là thứ quảng cáo trên tivi còn "Muốn" là sách giáo khoa'],
               'Phân biệt Cần và Muốn là kĩ năng số một giúp chi tiêu đúng trọng tâm không lãng phí tiền bạc.', 'Phân biệt giữa Cần (Needs) và Muốn (Wants)'),
            _q(9, 2, 'basic', 'Món đồ nào sau đây thuộc nhóm "CẦN thiết yếu" chuẩn bị cho năm học mới của học sinh Lớp 5?',
               'Vở ô li sạch, bút mực viết tốt, thước kẻ và đôi giày thể thao vừa chân cho giờ Thể dục',
               ['Năm chiếc móc khóa nhựa gắn cặp hình nhân vật hoạt hình đang theo trào lưu', 'Hai hộp bánh snack cay giá đắt gấp ba bình thường để khoe bạn', 'Bộ xếp hình giá hai triệu đồng mua theo mốt tuần này'],
               'Ưu tiên hoàn tất danh sách đồ dùng thiết yếu trước rồi mới cân nhắc món sở thích nếu còn dư ngân sách hợp lí.', 'Nhận diện nhu cầu thiết yếu chuẩn bị đi học'),
            _q(9, 3, 'basic', 'Theo mô hình quản lí tiền mừng tuổi hoặc tiền tiêu vặt bằng "3 Chiếc Lọ Tiết kiệm", ba mục đích chia phần tiền hợp lí nhất gồm những hũ nào?',
               'Hũ Tiết kiệm (tích lũy cho mục tiêu lớn dài hạn) – Hũ Chi tiêu (mua đồ học tập cần thiết) – Hũ Sẻ chia (giúp đỡ cộng đồng, tặng quà người thân)',
               ['Hũ Ăn quà vặt hết ngay – Hũ Mua đồ chơi dùng một lần – Hũ Vứt bỏ mất', 'Chỉ dùng duy nhất một túi để tiêu sạch hết 100% ngay trong chiều thứ Bảy', 'Giấu tiền rải rác khắp mọi ngăn kéo không đếm bao giờ'],
               'Chia ngay vào 3 hũ trước khi tiêu giúp em vừa biết tích góp tương lai vừa nuôi dưỡng lòng nhân ái biết sẻ chia.', 'Mô hình 3 hũ Tiết kiệm - Chi tiêu - Sẻ chia'),
            _q(9, 4, 'basic', 'Quan sát bảng kế hoạch tài chính nhỏ Lớp 5 sau đây. Khi nhìn thấy một món đồ chơi mới lạ trên kệ siêu thị mà rất thích, quy tắc "Chờ 48 giờ" giúp ích gì cho người mua hàng thông minh?',
               'Cho tâm trí thời gian nguội bớt cảm xúc hứng thú nhất thời để suy xét lại xem mình có thực sự cần dùng nó lâu dài hay chỉ thích chớp nhoáng',
               ['Giúp món đồ chơi tự động chạy theo mình về nhà miễn phí', 'Để tới ngày thứ ba mua một lúc mười món giống nhau cho nhiều hơn', 'Làm người bán hàng buộc phải đóng cửa tiệm'],
               'Phần lớn quyết định mua sắm bốc đồng sẽ giảm nhiệt hẳn sau 1–2 ngày suy nghĩ lại.', 'Quy tắc "Chờ 48 giờ" tránh mua sắm bốc đồng',
               fig=table_fig('Quản lí Tài chính Lớp 5', ['Thói quen tài chính', 'Ý nghĩa thực tiễn'], [['Cần trước - Muốn sau', 'Ưu tiên học, khỏe'], ['3 Hũ tài chính nhỏ', 'Tiết kiệm-Tiêu-Chia'], ['Quy tắc chờ 48 giờ', 'Tránh mua bốc đồng'], ['Ghi sổ tay chi tiêu', 'Theo dõi thu chi']])),
            _q(9, 5, 'basic', 'Mỗi đồng tiền bố mẹ kiếm được mang về chăm lo gia đình bắt nguồn từ đâu, và điều đó nhắc nhở em thái độ gì khi xin mua đồ dùng mới?',
               'Bắt nguồn từ công sức lao động chăm chỉ, thời gian và trí tuệ vất vả của cha mẹ; nên em phải trân trọng, không vòi vĩnh lãng phí hay so bì đắt rẻ với bạn',
               ['Tiền tự động sinh ra không giới hạn bên trong máy rút tiền ATM bất cứ lúc nào bấm nút', 'Bố mẹ không cần đi làm vẫn có tiền vô tận trong ví', 'Nên đòi mua mọi món đắt nhất chỉ để bằng bạn trong lớp'],
               'Thấu hiểu giá trị lao động đằng sau đồng tiền giúp trẻ biết trân trọng từng bữa cơm, cuốn vở và món đồ chơi.', 'Trân trọng giá trị công sức lao động của cha mẹ'),
            _q(9, 6, 'basic', 'Việc giữ một cuốn sổ nhỏ (hoặc bảng ghi chép cuối tuần) ghi lại số tiền mình có và các khoản nhỏ đã chi tiêu mang lại lợi ích rõ rệt nhất là gì?',
               'Giúp nhìn rõ những khoản chi vặt lặt vặt cộng dồn rất tốn kém (như tiền quà vặt cổng trường) để tự điều chỉnh tiết kiệm đạt mục tiêu mong muốn',
               ['Làm cho số tiền trong ví tự động nhân lên gấp đôi qua một đêm', 'Để khoe số tiền mừng tuổi với toàn bộ người lạ trên mạng', 'Giúp không cần học môn Toán ở trường nữa'],
               '"Cái gì đo lường được thì quản lí được" – ghi chép đơn giản làm sáng tỏ mọi lỗ hổng chi tiêu nhỏ.', 'Lợi ích ghi chép sổ tay chi tiêu cá nhân'),
            _q(9, 7, 'application', 'Tết vừa rồi em được ông bà mừng tuổi 500.000 đồng (được bố mẹ tin tưởng cho tự tập quản lí một phần dưới sự hướng dẫn). Cách chia phân bổ 3 hũ hợp lí nhất là phương án nào?',
               'Cất 300.000đ (60%) vào hũ Tiết kiệm mua chiếc xe đạp hoặc bộ sách lớn mơ ước, dành 100.000đ chi dùng hợp lí và 100.000đ bỏ hũ Sẻ chia ủng hộ bạn khó khăn',
               ['Cầm cả 500.000đ đi mua hết kẹo mút và thẻ hình chơi một buổi chiều cho hết sạch', 'Xé rách hoặc ném lung tung tiền lẻ xuống gầm giường', 'Đòi bố mẹ phải bù thêm gấp mười lần số tiền đó để mua điện thoại đắt tiền'],
               'Biết ưu tiên phần lớn (50–60%) cho tích lũy mục tiêu lớn và trích phần sẻ chia là nền tảng tài chính vững vàng.', 'Thực hành phân bổ tiền mừng tuổi theo 3 hũ'),
            _q(9, 8, 'application', 'Một món đồ chơi mới trên mạng đang là "trào lưu" của các bạn trong lớp giá 180.000 đồng. Em đang tiết kiệm tiền để mua bộ sách Bách khoa Khoa học giá 220.000 đồng (đã có 170.000 đồng). Nếu mua món đồ theo trào lưu thì điều gì xảy ra?',
               'Số tiền tiết kiệm tụt về gần 0 và giấc mơ sở hữu bộ sách khoa học yêu thích bị lùi lại nhiều tháng nữa; em chọn kiên định giữ tiền cho mục tiêu quan trọng hơn',
               ['Chẳng sao cả, tiêu hết 180.000đ vẫn còn dư nguyên 170.000đ để mua sách ngay lập tức', 'Bộ sách khoa học sẽ tự giảm giá xuống còn 0 đồng vào ngày mai', 'Mua món đồ chơi theo mốt xong có thể xài mãi suốt 20 năm không chán'],
               'Hiểu "chi phí cơ hội" (chọn món A nghĩa là mất tiền mua món B) giúp em ra quyết định tiêu tiền sáng suốt.', 'Hiểu chi phí cơ hội khi quyết định chi tiêu'),
            _q(9, 9, 'application', 'Em muốn mua tặng mẹ một chiếc khăn quàng cổ giá 120.000 đồng nhân dịp sinh nhật tháng tới bằng chính tiền tiết kiệm nhỏ của mình. Mỗi tuần em tiết kiệm được 25.000 đồng tiền ăn sáng/chi tiêu vặt hợp lí (không nhịn đói) thì cần kiên trì khoảng mấy tuần?',
               'Ít nhất 5 tuần (vì 5 × 25.000 = 125.000 đồng, đủ 120.000 đồng mà vẫn giữ thói quen ăn uống khỏe mạnh mỗi ngày)',
               ['Chỉ cần đúng 1 tuần là 25.000 đồng lớn hơn 120.000 đồng rồi', 'Nhịn hoàn toàn bữa sáng cả 5 ngày cho có đủ tiền thật nhanh dù ngất xỉu', 'Đòi bố lấy tiền của bố đưa cho mình đi mua rồi nhận công của mình'],
               'Lập kế hoạch tiết kiệm đều đặn hằng tuần đạt mục tiêu ý nghĩa mà vẫn bảo đảm dinh dưỡng khỏe mạnh.', 'Lập kế hoạch tiết kiệm ngắn hạn thực tế'),
            _q(9, 10, 'application', 'Quan sát biểu đồ minh họa hiệu quả tích lũy của thói quen "Tiết kiệm nhỏ đều đặn mỗi tuần 20.000đ" trong suốt 1 năm học (36 tuần) so với tiêu vặt hết sạch mỗi tuần. Con số sau 36 tuần cho thấy bài học tài chính nào?',
               'Chỉ 20.000đ nhỏ mỗi tuần sau 36 tuần sẽ tích lũy thành 720.000đ đủ mua chiếc xe đạp tốt hoặc đóng góp quỹ học bổng ý nghĩa – sức mạnh của sự tích lũy bền bỉ',
               ['Tiết kiệm 20.000đ mỗi tuần sau một năm chỉ thu lại được đúng 20.000đ', 'Khoản tiền nhỏ dưới 50.000đ chẳng bao giờ có giá trị gì nên cứ tiêu sạch ngay', 'Tiết kiệm càng đều thì tổng tiền càng nhỏ dần về 0'],
               'Khoản tiền lẻ tưởng nhỏ nhưng kiên trì đều đặn qua nhiều tuần tạo ra giá trị bất ngờ ("Tích tiểu thành đại").', 'Sức mạnh của tích lũy đều đặn từng khoản nhỏ',
               fig=bars_fig('Tiền tích lũy 20k/tuần (nghìn đồng)', ['Sau 4 tuần (1 tháng)', 'Sau 12 tuần (3 tháng)', 'Sau 24 tuần (6 tháng)', 'Sau 36 tuần (1 năm học)'], [80, 240, 480, 720])),
            _q(9, 11, 'application', 'Khi đi siêu thị cùng gia đình, một biển quảng cáo treo chữ đỏ thật to: "GIẢM GIÁ SỐC 50% CHỈ HÔM NAY – MUA 2 TẶNG 1!" cho một loại bánh kẹo ít dinh dưỡng mà nhà chưa ai cần ăn. Thái độ mua sắm tỉnh táo nhất là gì?',
               'Kiểm tra xem gia đình có thực sự cần không trước; mua một món đang giảm giá mà mình không cần vẫn là lãng phí 100% số tiền bỏ ra',
               ['Cứ thấy chữ Giảm giá 50% là phải ôm ngay năm thùng bỏ vào xe đẩy không cần nghĩ', 'Tin rằng mua đồ giảm giá không cần dùng sẽ giúp nhà mình giàu lên tức khắc', 'Bật khóc năn nỉ mẹ mua bằng được kẻo hết khuyến mãi'],
               'Không để chiêu tiếp thị "khan hiếm giảm giá" điều khiển ví tiền; giá trị món đồ nằm ở việc mình CÓ DÙNG NÓ KHÔNG.', 'Tỉnh táo trước bẫy khuyến mãi giảm giá'),
            _q(9, 12, 'application', 'Trong lớp có phong trào "Nuôi heo đất Khuyến học" mỗi bạn đóng góp tự nguyện vài nghìn đồng tiền tiết kiệm chi tiêu vặt mỗi tuần để cuối kì tặng bạn có hoàn cảnh khó khăn mua xe đạp. Em tham gia sao cho ý nghĩa nhất?',
               'Chủ động bớt một phần tiền ăn vặt/đồ chơi không cần thiết hằng tuần bỏ heo đất bằng tấm lòng vui vẻ, không khoe khoang số tiền ít nhiều với bạn',
               ['Xin tiền riêng của bố mẹ đóng thật to rồi khoe ầm ĩ khắp trường để lấy tiếng', 'Đòi bạn bên cạnh phải đóng đúng bằng mình mới cho ngồi cùng bàn', 'Không thèm góp xu nào dù vừa mua hộp đồ chơi 300 nghìn đồng'],
               'Hũ Sẻ chia quý nhất ở tấm lòng tự nguyện trích từ phần tiêu dùng của chính mình và sự khiêm tốn chân thành.', 'Ý nghĩa thực sự của phong trào tiết kiệm sẻ chia'),
            _q(9, 13, 'advanced', 'Nhiều bạn nhỏ lầm tưởng rằng "Người tiết kiệm là người keo kiệt bủn xỉn không bao giờ dám mua gì hay giúp ai". Sự khác biệt bản chất giữa "Tiết kiệm thông minh" và "Keo kiệt ích kỉ" là gì?',
               'Tiết kiệm thông minh là cắt bỏ lãng phí để đầu tư cho sức khỏe, tri thức và sẻ chia đúng lúc; còn keo kiệt là chỉ giữ khư khư ích kỉ',
               ['Không có gì khác nhau cả, tiết kiệm đồng nghĩa với nhịn ăn và không giúp đỡ bất kì ai', 'Người tiết kiệm thông minh phải vứt hết sách vở đi để đỡ tốn tiền mua bút', 'Người rộng rãi là người tiêu sạch hết sạch tiền ngay trong một ngày cho đồ chơi'],
               'Tiết kiệm đúng cách tạo nguồn lực tự chủ để vừa chăm lo bản thân tốt vừa hào phóng giúp đời.', 'Phân biệt tiết kiệm thông minh và keo kiệt'),
            _q(9, 14, 'advanced', 'Khi chiếc áo khoác cũ vẫn còn ấm đẹp nhưng hơi ngắn tay một chút so với năm ngoái, có gia đình đem giặt sạch tặng em nhỏ hàng xóm thay vì vứt đi và chỉ mua một chiếc mới vừa vặn. Giá trị kép của hành động này là gì?',
               'Kết hợp hài hòa giữa Tài chính hợp lí (tối ưu giá trị sử dụng quần áo còn tốt) – Lối sống Xanh (giảm rác dệt may) – Tình người sẻ chia ấm áp',
               ['Chỉ làm tốn thêm thời gian giặt giũ chẳng có ý nghĩa gì cả', 'Áo cũ mặc một mùa xong bắt buộc phải ném thẳng vào sọt rác mới là văn minh', 'Tặng đồ lành sạch cho người cần là biểu hiện của việc lãng phí'],
               'Tiêu dùng bền vững gắn liền tài chính gia đình tiết kiệm với bảo vệ hành tinh và kết nối cộng đồng.', 'Giá trị kép của tái sử dụng và sẻ chia đồ dùng tốt'),
            _q(9, 15, 'advanced', 'Tại sao rèn thói quen quản lí tiền mừng tuổi và tiền tiêu vặt ngay từ Lớp 5 lại giúp học sinh tránh xa nhiều cạm bẫy khi lên Trung học Cơ sở?',
               'Vì học sinh sớm biết lập kế hoạch, nói không với vay mượn tiêu xài theo bạn bè, nhận biết quảng cáo thổi phồng và quý trọng giá trị đồng tiền lao động',
               ['Vì học sinh Lớp 5 biết giữ tiền sẽ không cần học bất kì môn văn hóa nào ở Lớp 6', 'Vì từ Lớp 6 trở đi mọi đồ dùng học tập đều miễn phí hoàn toàn không cần mua', 'Vì quản lí tiền chỉ là đếm xem tờ tiền màu gì đẹp nhất'],
               'Nền tảng trí tuệ tài chính sớm hình thành bản lĩnh tự chủ trước cám dỗ vật chất tuổi thiếu niên.', 'Lợi ích dài hạn của giáo dục tài chính tuổi Lớp 5'),
        ]
    ))

    # BÀI 10: Tự chủ Cảm xúc, Vượt qua Căng thẳng Thi cử và Áp lực Bạn bè
    lessons.append(make_lesson(
        'lssong5-c4', 'lssong5-b10', 'Bài 10. Tự chủ Cảm xúc, Vượt qua Căng thẳng Thi cử và Áp lực Bạn bè', 10,
        'Nhận diện các tín hiệu căng thẳng (tim đập nhanh, mất ngủ, cáu gắt) trước kì kiểm tra cuối cấp; thực hành kĩ thuật thở hộp 4-4-4-4 điều hòa cảm xúc, ôn tập khoa học và vững vàng trước áp lực lôi kéo tiêu cực của bạn bè',
        ['Nhận diện dấu hiệu lo âu thi cử và kĩ thuật hít thở điều hòa bình tĩnh', 'Chiến lược ôn tập đều đặn thay cho học nhồi nhét đêm trước ngày thi', 'Bản lĩnh đứng vững trước áp lực bạn bè (Peer pressure) tiêu cực'],
        [
            _q(10, 1, 'basic', 'Trước kì kiểm tra cuối kì quan trọng, dấu hiệu cơ thể nào cho thấy em đang bị căng thẳng lo âu quá mức cần tạm nghỉ thư giãn điều hòa lại?',
               'Tim đập nhanh hồi hộp, tay ra mồ hôi lạnh, khó ngủ ban đêm, đau bụng nhẹ hoặc đầu óc trống rỗng dễ cáu gắt vô cớ',
               ['Cơ thể khỏe khoắn thư thái, ngủ ngon đủ giấc và tập trung đọc bài dễ dàng', 'Mỉm cười vui vẻ trò chuyện hòa đồng cùng mọi người', 'Ăn ngon miệng và vận động nhẹ nhàng buổi chiều'],
               'Lắng nghe tín hiệu cảnh báo từ cơ thể là bước đầu tiên để điều chỉnh nhịp học nghỉ hợp lí kịp thời.', 'Nhận diện dấu hiệu cơ thể bị căng thẳng thi cử'),
            _q(10, 2, 'basic', 'Kĩ thuật "Hít thở Hộp (Box Breathing 4-4-4-4)" giúp làm dịu nhanh nhịp tim và cơn hồi hộp ngay trước khi bước vào phòng thi thực hiện theo nhịp nào?',
               'Hít sâu bằng mũi 4 giây – Nín giữ nhẹ nhàng 4 giây – Thở ra chậm đều bằng miệng 4 giây – Nghỉ giữ phổi trống 4 giây rồi lặp lại vài vòng',
               ['Nín thở hoàn toàn 3 phút liền không hít khí nào', 'Thở hổn hển thật nhanh dồn dập 50 lần trong 10 giây', 'Hét thật to hết hơi rồi chạy vòng quanh hành lang'],
               'Nhịp thở chậm đều 4-4-4-4 kích hoạt hệ thần kinh đối giao cảm giúp cơ thể bình tĩnh sáng suốt trở lại chỉ trong 1 phút.', 'Thực hành kĩ thuật thở hộp 4-4-4-4 giảm hồi hộp'),
            _q(10, 3, 'basic', 'Cách chuẩn bị ôn tập nào hiệu quả nhất giúp giữ tinh thần tự tin thoải mái mà KHÔNG bị hoảng loạn trước bài kiểm tra cuối năm Lớp 5?',
               'Chia nhỏ nội dung ôn tập đều đặn từ 1–2 tuần trước khi thi, luyện giải đề mẫu vừa sức và đêm trước ngày thi đi ngủ sớm đủ giấc',
               ['Thức trắng hoàn toàn cả đêm trước hôm thi nhồi nhét đọc lại cả năm học', 'Chơi suốt cả tháng rồi sáng hôm thi vừa đi đường vừa mở sách học thuộc', 'Uống liên tiếp hai cốc cà phê đặc của người lớn lúc 23 giờ đêm'],
               'Giấc ngủ trước ngày thi giúp não bộ sắp xếp kết nối lại kiến thức; thức khuya nhồi nhét làm giảm trí nhớ ngắn hạn.', 'Ôn tập dàn đều và ngủ đủ trước ngày kiểm tra'),
            _q(10, 4, 'basic', 'Quan sát bảng giải pháp cân bằng cảm xúc Lớp 5 dưới đây. "Áp lực đồng trang lứa tiêu cực" (Negative Peer Pressure) là hiện tượng gì ở trường học?',
               'Việc một nhóm bạn chê bai hoặc dọa nghỉ chơi để ép buộc em làm theo điều sai trái hoặc nguy hiểm mà bản thân em không muốn làm',
               ['Việc các bạn cùng thi đua đọc nhiều sách hay và tập thể dục mỗi sáng', 'Việc cô giáo nhắc học sinh làm đủ bài tập về nhà', 'Việc các bạn rủ nhau nhặt rác làm sạch sân trường'],
               'Nhận ra ranh giới áp lực tích cực (cùng tiến bộ) với áp lực tiêu cực (lôi kéo sai trái) giúp em giữ vững bản lĩnh.', 'Phân biệt áp lực bạn bè tiêu cực và tích cực',
               fig=table_fig('Cân bằng Cảm xúc Lớp 5', ['Khó khăn gặp phải', 'Cách điều chỉnh tốt'], [['Hồi hộp trước thi', 'Thở hộp 4-4-4-4'], ['Bài tập quá nhiều', 'Chia nhỏ 25 phút'], ['Cơn giận dâng cao', 'Tạm rời, uống nước'], ['Bạn ép làm điều xấu', 'Nói KHÔNG, rời đi']])),
            _q(10, 5, 'basic', 'Trong phòng thi, khi vừa đọc qua đề thấy có một câu khó chưa nghĩ ra cách giải ngay, phản xạ thông minh giúp giữ bình tĩnh và đạt điểm tối đa phần làm được là gì?',
               'Hít một hơi sâu, tạm bỏ qua câu khó để làm chắc chắn toàn bộ các câu dễ – trung bình trước rồi quay lại tập trung xử lí câu khó sau',
               ['Ngồi khóc òa lên ngay tại chỗ suốt 30 phút không viết chữ nào vào giấy', 'Ngồi cắn bút nhìn chằm chằm một câu khó tới lúc trống thu bài mới sực nhớ các câu sau', 'Quay sang liếc nhìn bài bạn bên cạnh để chép cho xong'],
               'Chiến thuật "Dễ làm trước, khó làm sau" xây dựng đà tâm lí tự tin và không đánh mất điểm chắc ăn ở phần sau đề.', 'Chiến thuật giữ bình tĩnh xử lí câu khó khi thi'),
            _q(10, 6, 'basic', 'Khi nhận kết quả một bài kiểm tra không cao như mong muốn dù mình đã cố gắng, thái độ tích cực kiểu "Tư duy phát triển" (Growth Mindset) là gì?',
               'Bình tĩnh xem kĩ từng lỗi sai để hiểu mình hổng kiến thức ở bước nào, rút kinh nghiệm cải thiện cách học cho lần kiểm tra tiếp theo',
               ['Tự kết luận rằng "Mình sinh ra đã dốt bẩm sinh, học mãi cũng vô ích!" rồi bỏ cuộc', 'Xé nát bài kiểm tra giấu xuống dưới đáy cặp không cho bố mẹ biết', 'Đổ lỗi tại đề thi ra sai và tại bạn ngồi cạnh làm mình phân tâm'],
               'Thất bại nhỏ là tấm bản đồ chỉ đúng chỗ cần bồi đắp; tư duy phát triển coi sai sót là bậc thang tiến bộ.', 'Áp dụng tư duy phát triển sau kết quả chưa như ý'),
            _q(10, 7, 'application', 'Một nhóm bạn thân rủ em: "Chiều nay bỏ tiết luyện chữ trốn ra quán điện tử chơi đi, không đi là đồ nhát gan không xứng chơi hội tụi này!". Em giữ vững lập trường bằng câu nói tự tin nào?',
               '"Tớ không bỏ tiết đâu vì giữ đúng nội quy lớp quan trọng hơn; hết giờ học về rồi tụi mình hẹn nhau đá bóng ở sân nhé!" rồi quay về lớp',
               ['Sợ bị chê nhát gan nên miễn cưỡng bỏ tiết trốn trường đi chơi game cùng nhóm bạn', 'Chửi bới to tiếng xô đẩy nhóm bạn kia ngay giữa cổng trường', 'Nói dối cô giáo là mình bị ốm rồi lén ra quán game'],
               'Người thực sự bản lĩnh dám làm điều đúng dù bị trêu chọc; rủ chuyển sang hoạt động lành mạnh khác vẫn giữ được tình bạn nếu họ tôn trọng mình.', 'Vững vàng từ chối rủ rê bỏ học đi chơi game'),
            _q(10, 8, 'application', 'Trong lúc tranh cãi gay gắt với em trai ở nhà về chiếc điều khiển tivi, em thấy mặt mình nóng bừng, tim đập thình thịch sắp nói lời xúc phạm em hoặc vung tay đánh em. Cách "Cấp cứu cơn giận" tại chỗ là gì?',
               'Dừng lại ngay không nói thêm lời nào, đi sang phòng khác uống một cốc nước mát, rửa mặt hoặc hít thở chậm 1 phút cho nguội bớt rồi mới quay lại nói nhẹ',
               ['Hét thật to hơn nữa và giật mạnh làm rơi vỡ luôn chiếc điều khiển', 'Đấm mạnh vào cánh cửa gỗ cho bõ cơn tức giận', 'Trút giận sang cả chú mèo đang ngủ trong góc nhà'],
               'Rời khỏi điểm nóng căng thẳng ("Time-out tích cực") 60 giây bảo vệ bản thân và người thân khỏi tổn thương không đáng có.', 'Kĩ năng "Time-out tích cực" hạ nhiệt cơn giận tại nhà'),
            _q(10, 9, 'application', 'Bạn Chi luôn đặt mục tiêu mọi môn phải đạt đúng 10 điểm tuyệt đối, nên chỉ cần sơ suất sai mất 0,5 điểm còn 9,5 điểm Chi đã khóc nức nở suốt hai ngày chẳng muốn ăn uống. Em khuyên Chi nhìn nhận thế nào?',
               'Điểm 9,5 đã là nỗ lực rất giỏi rồi; cầu toàn quá mức tự làm khổ mình, hãy ghi nhận tiến bộ và coi 0,5 điểm thiếu như bài học thú vị',
               ['Khuyên Chi phải khóc to hơn nữa và thức trắng cả tuần không ngủ cho nhớ đời', 'Chê Chi đạt 9,5 điểm đúng là kết quả quá tệ hại đáng xấu hổ', 'Khuyên Chi không cần đi thi nữa cho đỡ sai điểm nào'],
               'Nỗ lực xuất sắc khác với chủ nghĩa cầu toàn cực đoan; trân trọng thành quả thật giữ niềm vui học tập dài lâu.', 'Giúp bạn thoát khỏi áp lực cầu toàn cực đoan'),
            _q(10, 10, 'application', 'Quan sát biểu đồ mức độ giảm căng thẳng của học sinh Lớp 5 khi áp dụng các hoạt động thư giãn lành mạnh giữa giờ ôn thi cuối kì. Hai biện pháp tự nhiên giúp giảm căng thẳng mạnh nhất là gì?',
               'Vận động chạy bộ chơi thể thao nhẹ ngoài trời (giảm 78%) và hít thở sâu – ngủ đủ 9 tiếng (giảm 72%), vượt xa việc ngồi chơi điện tử nhiều giờ',
               ['Chơi điện tử liên tục 4 tiếng giúp giảm căng thẳng tới 95%', 'Thức đêm uống nước tăng lực giúp tinh thần sảng khoái nhất', 'Ngồi lì một chỗ suốt cả ngày không nói chuyện với ai tốt hơn cả'],
               'Vận động thể chất giải phóng endorphin tự nhiên xua tan hoóc-môn căng thẳng hiệu quả hơn hẳn giải trí thụ động trước màn hình.', 'Chọn biện pháp giải tỏa căng thẳng khoa học nhất',
               fig=bars_fig('Hiệu quả giảm căng thẳng khi ôn thi (%)', ['Chơi thể thao ngoài trời', 'Thở sâu, ngủ đủ giấc', 'Nghe nhạc, vẽ tranh nhẹ', 'Chơi game trên điện thoại'], [78, 72, 64, 22])),
            _q(10, 11, 'application', 'Phương pháp học "Pomodoro 25/5" rất hợp với học sinh Lớp 5 khi ôn tập lượng bài khá nhiều: ngồi tập trung tuyệt đối làm bài trong 25 phút rồi đứng dậy nghỉ 5 phút. Trong 5 phút nghỉ ngắn đó, em nên làm gì cho mắt và não phục hồi tốt nhất?',
               'Đứng dậy vươn vai giãn cơ nhẹ, uống vài ngụm nước lọc và nhìn ra khoảng xanh ngoài cửa sổ chứ KHÔNG mở điện thoại xem video lướt mạng',
               ['Mở ngay điện thoại ra chơi một ván game kéo dài sang tận 40 phút', 'Nằm vật ra ngủ say luôn 3 tiếng đồng hồ', 'Cúi sát mặt xuống bàn đọc tiếp sách truyện chữ nhỏ xíu'],
               '5 phút nghỉ không màn hình giúp não thực sự thư giãn sẵn sàng quay lại hiệp học 25 phút tiếp theo trơn tru.', 'Nghỉ giải lao đúng cách theo nhịp học 25/5'),
            _q(10, 12, 'application', 'Một người bạn mới chuyển trường tới lớp chưa quen ai nên giờ ra chơi hay ngồi lặng lẽ một mình có vẻ lo lắng. Cử chỉ ấm áp nào giúp bạn ấy nhanh chóng hòa nhập bớt căng thẳng?',
               'Chủ động mỉm cười sang chào hỏi làm quen, giới thiệu sơ đồ lớp học và rủ bạn cùng tham gia trò chơi nhẹ cùng nhóm mình giờ ra chơi',
               ['Tụ tập đứng xa xì xào chỉ trỏ đoán xem vì sao bạn chuyển trường', 'Cấm bạn ấy ngồi vào khu vực ghế đá của nhóm mình', 'Làm ngơ suốt một tháng xem bạn có tự dám mở miệng nói trước không'],
               'Một lời chào chủ động thân thiện biến ngày đầu tiên bỡ ngỡ của bạn mới thành kỉ niệm đẹp khó quên.', 'Giúp bạn mới chuyển trường giảm bỡ ngỡ hòa nhập'),
            _q(10, 13, 'advanced', 'Nhiều học sinh nghĩ rằng "Người thông minh bản lĩnh là người không bao giờ biết sợ hãi hay lo lắng trước bất kì cuộc thi nào!". Nhận xét tâm lí học đúng về cảm xúc lo lắng nhẹ trước khi thi là gì?',
               'Lo lắng vừa phải là phản ứng tự nhiên giúp não tăng sự tỉnh táo tập trung, miễn sao giữ bình tĩnh không để hoảng loạn mất kiểm soát',
               ['Chỉ có học sinh kém mới từng cảm thấy hồi hộp trước ngày thi', 'Ai cảm thấy tim hơi hồi hộp trước lúc lên sân khấu thuyết trình đều chắc chắn thất bại', 'Để hết lo lắng thì phải vứt hết sách vở đi không ôn thi chữ nào'],
               'Không cần diệt bỏ hoàn toàn cảm giác hồi hộp; hãy đón nhận nó như năng lượng giúp mình tập trung chuẩn bị kĩ hơn.', 'Hiểu đúng vai trò của lo lắng nhẹ tích cực'),
            _q(10, 14, 'advanced', 'Tại sao nói "Quản lí cảm xúc không phải là đè nén giấu biệt nỗi buồn hay cơn giận vào bên trong mà là nhận diện gọi tên nó rồi biểu đạt một cách an toàn không làm đau mình và người khác"?',
               'Đè nén lâu ngày khiến cảm xúc dồn ứ dễ bùng nổ hoặc gây stress; gọi tên và giải tỏa lành mạnh (viết nhật kí, chia sẻ, vận động) giúp cân bằng tâm trí',
               ['Vì người biết quản lí cảm xúc không bao giờ được phép khóc hay buồn trong suốt cuộc đời', 'Vì giận ai thì cứ đập vỡ đồ đạc ngay lập tức là biểu đạt an toàn nhất', 'Vì cảm xúc tự động tan biến vĩnh viễn nếu giả vờ cười lớn suốt ngày'],
               'Mọi cảm xúc (vui, buồn, giận, sợ) đều có giá trị thông điệp riêng; điều quan trọng là cách HÀNH XỬ văn minh sau cảm xúc đó.', 'Phân biệt điều chỉnh cảm xúc với kìm nén cực đoan'),
            _q(10, 15, 'advanced', 'Khi bố mẹ lỡ kì vọng quá cao khiến em cảm thấy áp lực nặng nề về điểm số chuyển cấp sắp tới, cách đối thoại trưởng thành nhất giữa hai thế hệ là gì?',
               'Chọn lúc cả nhà vui vẻ thoải mái tâm sự chân thành cảm giác áp lực của mình, trình bày kế hoạch tự học cố gắng hết sức và mong bố mẹ đồng hành khích lệ',
               ['Im lặng giận dỗi bỏ cơm hai ngày để phản đối bố mẹ', 'Cố tình làm bài kiểm tra toàn điểm 1 để trả thù bố mẹ', 'Quát to lên rằng chuyện học là việc của con không liên quan tới bố mẹ'],
               'Đối thoại cởi mở nhẹ nhàng giúp cha mẹ hiểu ngưỡng sức của con và chuyển kì vọng áp lực thành sự động viên ấm áp.', 'Kĩ năng đối thoại cởi mở giảm áp lực kì vọng'),
        ]
    ))

    # BÀI 11: Lối sống Xanh Bền vững, Giảm Nhựa và Bảo vệ Hệ sinh thái Địa phương
    lessons.append(make_lesson(
        'lssong5-c4', 'lssong5-b11', 'Bài 11. Lối sống Xanh Bền vững, Giảm Nhựa và Bảo vệ Hệ sinh thái Địa phương', 11,
        'Nâng cao ý thức bảo vệ môi trường từ phạm vi cá nhân sang cộng đồng tuổi Lớp 5: hiểu tác hại vi nhựa trong chuỗi thức ăn, bảo vệ nguồn nước sạch ao hồ sông ngòi và thực hành lối sống xanh không rác nhựa thừa',
        ['Nhận diện tác hại rác nhựa dùng một lần và vi nhựa (Microplastics)', 'Bảo vệ nguồn nước sạch sông hồ địa phương: không xả rác thải sinh hoạt xuống kênh mương', 'Thực hành dự án Sống Xanh nhóm Lớp 5 tại trường và khu dân cư'],
        [
            _q(11, 1, 'basic', 'Những mảnh nhựa siêu nhỏ kích thước dưới 5 mm phân rã từ chai nhựa, túi nilon hay hộp xốp trôi ra sông biển được gọi là gì và gây hại thế nào?',
               'Vi nhựa (Microplastics) – dễ bị cá, tôm, sinh vật biển nuốt nhầm rồi tích tụ dần đi ngược vào chuỗi thức ăn của chính con người',
               ['Mảnh dinh dưỡng xanh giúp cá đại dương lớn nhanh gấp đôi', 'Hạt muối biển tự nhiên hòa tan hết sau một đêm mưa', 'Chất tẩy sạch làm nước sông biển trong vắt tinh khiết hơn'],
               'Rác nhựa không phân hủy sinh học hoàn toàn mà vỡ vụn thành vi nhựa xâm nhập nguồn nước uống và thực phẩm hằng ngày.', 'Hiểu tác hại của Vi nhựa trong chuỗi thức ăn'),
            _q(11, 2, 'basic', 'Những món đồ nhựa dùng một lần nào trong sinh hoạt hằng ngày học sinh Lớp 5 có thể cắt giảm thay thế dễ dàng nhất bằng đồ dùng bền lâu?',
               'Túi nilon đi chợ, ống hút nhựa, cốc nhựa, thìa nĩa nhựa và chai nước suối nhỏ dùng một lần',
               ['Mũ bảo hiểm xe máy đạt chuẩn chất lượng', 'Ống nghe y tế bằng thép của bác sĩ bệnh viện', 'Cầu dao chống giật an toàn trong tủ điện gia đình'],
               'Thay thế bằng bình nước cá nhân, hộp cơm thủy tinh/inox, túi vải và ống hút inox – tre giảm hàng tấn rác nhựa khó phân hủy.', 'Nhận diện và cắt giảm nhựa dùng một lần'),
            _q(11, 3, 'basic', 'Hành động nào gây ô nhiễm trực tiếp nghiêm trọng nhất tới dòng sông, ao hồ và cống thoát nước tại khu vực nơi em sinh sống?',
               'Vứt bọc rác sinh hoạt, xác động vật chết hay đổ dầu mỡ thải – nước tẩy rửa đậm đặc thẳng xuống lòng kênh mương, ao hồ',
               ['Trồng hàng cây xanh giữ đất dọc hai bên bờ kè công viên ven hồ', 'Thu gom rác thải nổi ven bờ bỏ vào thùng rác phân loại trên bờ', 'Báo cơ quan môi trường khi phát hiện ống xả nước thải đục ngầu có mùi lạ'],
               'Mỗi bọc rác vứt xuống kênh không chỉ làm thối nước ngập úng cống thoát nước mùa mưa mà còn chảy thẳng ra biển lớn.', 'Bảo vệ dòng sông, kênh mương sạch rác'),
            _q(11, 4, 'basic', 'Quan sát bảng Thực hành Công dân Xanh Lớp 5 sau đây. Khi cả lớp tổ chức đi tham quan dã ngoại sinh thái ở rừng quốc gia hoặc bãi biển, quy tắc "Không để lại gì ngoài dấu chân" có nghĩa là gì?',
               'Thu gom mang về hết toàn bộ rác thải của đoàn mình không sót một vỏ bánh nhỏ, không bẻ cây bắt thú rừng hay khắc chữ lên đá – thân cây',
               ['Chụp thật nhiều ảnh rồi bỏ lại toàn bộ hộp xốp cơm trưa trên bãi cỏ', 'Giẫm đạp lên tất cả các bụi hoa rừng để tạo đường đi mới', 'Bắt cá nhỏ và nhặt san hô sống nhét vào chai mang về nhà nuôi'],
               'Du lịch sinh thái có trách nhiệm giữ nguyên vẹn hệ sinh thái tự nhiên cho muôn loài và thế hệ mai sau.', 'Quy tắc du lịch sinh thái "Không để lại rác"',
               fig=table_fig('Công dân Xanh Lớp 5', ['Lĩnh vực hành động', 'Việc làm bền vững'], [['Đi chợ, mua đồ', 'Mang túi vải riêng'], ['Uống nước đi học', 'Dùng bình cá nhân'], ['Nguồn nước sông hồ', 'Không xả rác xuống'], ['Khi đi dã ngoại', 'Mang hết rác về']])),
            _q(11, 5, 'basic', 'Với dầu ăn chiên rán thừa đã dùng xong ở căn bếp gia đình, vì sao bố mẹ KHÔNG ĐƯỢC đổ thẳng xuống chậu rửa bát hay cống thoát nước?',
               'Dầu mỡ nguội sẽ đông đặc kết mảng bám chặt làm tắc nghẽn đường ống cống khu phố và tạo màng váng cản oxi chết cá ở sông hồ',
               ['Vì dầu ăn chảy xuống cống sẽ biến thành đá quý màu vàng', 'Vì dầu mỡ giúp đường ống nhựa mềm dẻo hơn', 'Để tránh làm ống thoát nước chạy quá nhanh'],
               'Cách đúng là để nguội dầu thừa, đổ vào chai nhựa kín hoặc thấm giấy bỏ gọn vào thùng rác (hoặc điểm thu gom tái chế dầu thải làm xà phòng công nghiệp).', 'Không đổ dầu mỡ thừa xuống bồn rửa'),
            _q(11, 6, 'basic', 'Thói quen tiết kiệm giấy trong học tập hằng ngày góp phần bảo vệ trực tiếp tài nguyên thiên nhiên nào trên Trái Đất?',
               'Giảm chặt phá rừng cây lấy gỗ làm bột giấy, đồng thời tiết kiệm lượng lớn nước và năng lượng điện dùng trong nhà máy sản xuất giấy',
               ['Chỉ tiết kiệm được lượng mực đỏ của thầy cô giáo', 'Giúp tăng lượng rác thải nhựa trong thùng rác trường học', 'Làm rừng cây biến mất nhanh hơn bình thường'],
               'Tận dụng giấy một mặt làm giấy nháp Toán và quyên góp giấy vụn tái chế cứu sống rất nhiều cây xanh trưởng thành.', 'Tiết kiệm giấy góp phần bảo vệ rừng xanh'),
            _q(11, 7, 'application', 'Đội Thiếu niên trường em chuẩn bị tổ chức buổi "Liên hoan chia tay cuối cấp Lớp 5". Nếu em được tham gia ban tổ chức, phương án tiệc nào vừa vui rộn ràng vừa hạn chế tối đa rác thải nhựa?',
               'Chuẩn bị bình nước lớn cùng cốc giấy/cốc rửa dùng lại cho cả lớp, bày hoa quả trên đĩa chung và trang trí lớp bằng banner vải – giấy thủ công có thể tái sử dụng',
               ['Phát cho mỗi bạn năm chai nhựa nhỏ, ba cốc nhựa và hai mươi đĩa xốp dùng xong ném thẳng sân', 'Bơm hàng trăm quả bóng bay cao su thả bay lên trời gây hại cho chim cá', 'Gói từng quả nho vào từng chiếc túi nilon riêng lẻ'],
               'Một sự kiện "Không rác nhựa dùng một lần" vẫn tràn đầy tiếng cười mà tránh thải ra hàng trăm món đồ nhựa xốp chỉ dùng trong 15 phút.', 'Tổ chức liên hoan cuối cấp xanh ít rác nhựa'),
            _q(11, 8, 'application', 'Thấy một bác hàng xóm vô tình xách túi rác sinh hoạt ra định ném xuống dòng kênh trước ngõ vì lười đợi xe rác buổi tối. Em góp ý tế nhị thế nào để bác vui vẻ thay đổi?',
               'Lễ phép chào rồi nói: "Bác ơi rác xuống kênh dễ làm tắc cống ngập ngõ mình lắm ạ, bác để con xách giúp ra đầu ngõ đúng giờ xe rác nhé!"',
               ['Đứng chống nạnh quát ầm lên chửi bác là người vô ý thức trước mặt cả xóm', 'Chạy lại đá tung túi rác ra giữa đường cho xe cán nát', 'Học theo bác cũng mang rác nhà mình ném xuống kênh cùng cho vui'],
               'Nêu rõ hệ quả trực tiếp ảnh hưởng ngay tới chính ngôi nhà của bác (ngập cống mùi hôi) kèm sự giúp đỡ lễ phép tạo chuyển biến rất hiệu quả.', 'Góp ý văn minh bảo vệ kênh mương ngõ xóm'),
            _q(11, 9, 'application', 'Gia đình bạn An vừa thay bình ắc quy xe máy cũ và bóng đèn huỳnh quang hỏng dài có chứa thủy ngân. Bố An định bỏ chung luôn vào thùng rác nhựa màu xanh của tổ dân phố. Em khuyên bố xử lí chuẩn môi trường ra sao?',
               'Gói bọc cẩn thận tránh vỡ phát tán thủy ngân, dán nhãn "Rác nguy hại" rồi mang tới điểm thu hồi rác điện tử – nguy hại hoặc nơi đổi ắc quy',
               ['Đập vỡ tan bóng đèn huỳnh quang trong nhà bếp rồi quét đổ vào bồn cầu', 'Bỏ chung vào thùng rác hữu cơ để ủ phân bón cây rau ăn', 'Ném bóng đèn cũ xuống ao cá cuối làng'],
               'Bóng đèn huỳnh quang chứa hơi thủy ngân độc thần kinh và ắc quy chứa chì – axit; tuyệt đối không đập vỡ hay vứt chung rác sinh hoạt.', 'Xử lí rác thải nguy hại bóng đèn và ắc quy cũ'),
            _q(11, 10, 'application', 'Quan sát biểu đồ kết quả thực nghiệm phân loại rác trong một tháng tại Trường Tiểu học Xanh sau khi đặt bộ 3 thùng rác có màu và hình vẽ minh họa rõ ràng. Kết quả chứng minh điều gì?',
               'Tỉ lệ rác tái chế thu hồi sạch tăng vọt từ 15% lên 62% trong khi rác chôn lấp hỗn hợp giảm sâu chỉ còn 14% nhờ mọi học sinh biết phân loại đúng ngay từ đầu',
               ['Đặt nhiều thùng rác màu sắc làm học sinh vứt rác bừa bãi ra sân nhiều hơn', 'Tỉ lệ rác tái chế giảm xuống bằng 0% sau một tháng thực hiện', 'Chỉ cần một thùng rác duy nhất trộn lẫn cả nước canh vào sách giấy là hiệu quả nhất'],
               'Hạ tầng phân loại trực quan kết hợp thói quen đổ cặn lỏng trước khi bỏ thùng tạo hiệu quả tái chế vượt trội.', 'Phân tích hiệu quả mô hình phân loại rác học đường',
               fig=bars_fig('Tỉ lệ phân loại rác tại trường (%)', ['Rác tái chế sạch', 'Rác hữu cơ ủ phân', 'Rác chôn lấp còn lại', 'Trước khi phân loại (tái chế)'], [62, 24, 14, 15])),
            _q(11, 11, 'application', 'Đầu mùa hè, khu dân cư thường gặp hiện tượng bọ gậy (lăng quăng) sinh sôi trong các vũng nước đọng tại lốp xe cũ, vỏ chai lọ vỡ hay chậu cảnh bỏ không ngoài sân dẫn tới dịch sốt xuất huyết. Hành động dọn môi trường ngăn dịch hiệu quả nhất là gì?',
               'Lật úp toàn bộ lu vại, xô chậu không dùng, dọn sạch vỏ chai lốp xe đọng nước mưa hằng tuần và thay nước bình hoa thường xuyên để muỗi không có nơi đẻ trứng',
               ['Đổ thêm thật nhiều nước ngọt có đường vào các vũng nước tù ngoài vườn', 'Xếp thật nhiều lốp xe cũ đựng đầy nước mưa quanh cửa sổ phòng ngủ', 'Đợi có dịch bệnh bùng phát toàn phường mới bắt đầu đi úp lu vại'],
               '"Không có lăng quăng, không có sốt xuất huyết" – diệt nguồn nước đọng vừa làm sạch cảnh quan vừa bảo vệ sức khỏe cả xóm.', 'Loại bỏ ổ nước đọng phòng muỗi sốt xuất huyết'),
            _q(11, 12, 'application', 'Khi chọn mua đồ ăn nhẹ hoặc đồ dùng cá nhân, bạn Lan ưu tiên thực phẩm đóng gói giấy, thực phẩm địa phương theo mùa thay cho đồ nhập khẩu xa xôi bọc nhiều lớp nhựa xốp. Lợi ích môi trường của thói quen này là gì?',
               'Giảm lượng khí thải vận chuyển đường dài (dấu chân carbon), giảm bao bì nhựa khó phân hủy và hỗ trợ nông sản tươi sạch địa phương',
               ['Làm tăng gấp năm lần lượng rác hộp xốp thải ra bãi rác mỗi ngày', 'Thực phẩm địa phương luôn phải dùng máy bay chở vòng quanh Trái Đất trước khi ăn', 'Đồ đóng gói nhiều lớp nhựa luôn giữ được không khí sạch hơn cây xanh'],
               'Tiêu dùng thực phẩm bản địa ít bao bì giúp giảm đồng thời rác thải nhựa lẫn phát thải nhà kính.', 'Lợi ích sinh thái của tiêu dùng thực phẩm bản địa ít nhựa'),
            _q(11, 13, 'advanced', 'Nhiều bạn nhỏ băn khoăn: "Một mình em không dùng túi nilon hôm nay thì đại dương có bớt ô nhiễm đâu vì ngoài kia vẫn có hàng triệu người dùng?". Lập luận nào trả lời thuyết phục nhất cho suy nghĩ này?',
               'Mọi thay đổi lớn đều bắt đầu từ thói quen nhỏ lan tỏa: một người bớt hàng trăm túi mỗi năm, gia đình bạn bè noi theo sẽ nhân lên rất nhiều',
               ['Đúng vậy, một người thì chắc chắn chẳng bao giờ tạo ra tác động gì nên cứ xả rác thoải mái', 'Chỉ cần đứng chờ tất cả mọi người trên thế giới làm trước rồi mình làm sau cùng', 'Một túi nilon vứt xuống sông tự động biến mất trước khi chảy ra biển'],
               'Hiệu ứng lan tỏa hành động cá nhân ("Think globally, act locally") biến mỗi học sinh thành hạt nhân thay đổi cả cộng đồng.', 'Sức mạnh lan tỏa của hành động xanh cá nhân'),
            _q(11, 14, 'advanced', 'Giữa hai khẩu hiệu bảo vệ môi trường: (1) Chỉ dọn sạch rác sau khi cả khu phố vừa xả bừa bãi; (2) Thiết kế thói quen sinh hoạt ngay từ đầu để không xả phát sinh rác bừa bãi. Vì sao cách (2) là giải pháp gốc rễ bền vững hơn?',
               'Dọn rác chỉ xử lí phần ngọn tốn công sức mà rác vẫn tái diễn; thay đổi thói quen giảm mua nhựa và phân loại tại nguồn mới giải quyết tận gốc',
               ['Vì cách (1) giúp mọi người cứ vứt rác khắp đường cho nhân viên quét đường có việc làm', 'Vì không xả rác làm đường phố trở nên mất vệ sinh hơn', 'Vì dọn rác xong không cần phân loại cứ đốt sạch ngoài sân là tốt nhất'],
               'Chuyển từ tư duy "xử lí hậu quả" sang "phòng ngừa tại nguồn" là chìa khóa của phát triển bền vững.', 'Giải pháp gốc rễ phòng ngừa rác thải tại nguồn'),
            _q(11, 15, 'advanced', 'Trong bức tranh bảo vệ hệ sinh thái địa phương, vì sao bảo vệ từng hàng cây xanh đô thị, vùng đầm lầy ao hồ tự nhiên không chỉ là "giữ cảnh đẹp" mà còn giúp thành phố chống ngập và giảm nóng mùa hè?',
               'Rễ cây và ao hồ thấm giữ nước mưa chống úng ngập hiệu quả, còn tán lá bốc hơi nước tạo bóng mát giúp hạ nhiệt mặt đường nhựa 3–5 độ C',
               ['Vì lá cây xanh phát ra luồng điện làm mặt đường bê tông đóng băng giữa mùa hè', 'Vì ao hồ tự nhiên không bao giờ chứa được một giọt nước mưa nào', 'Lấp hết ao hồ đi đổ bê tông kín giúp nước mưa thấm xuống lòng đất nhanh gấp mười lần'],
               'Hạ tầng xanh (Green Infrastructure: cây xanh, hồ điều hòa, đất thấm nước) là bộ máy điều hòa khí hậu và chống ngập vô giá của tự nhiên.', 'Vai trò sinh thái điều hòa khí hậu và chống ngập của cây xanh'),
        ]
    ))

    # BÀI 12: Công dân Nhỏ Chuẩn mực – Tự tin Bước sang Trung học Cơ sở
    lessons.append(make_lesson(
        'lssong5-c4', 'lssong5-b12', 'Bài 12. Công dân Nhỏ Chuẩn mực – Tự tin Bước sang Trung học Cơ sở', 12,
        'Tổng kết hành trang kĩ năng sống toàn cấp Tiểu học: làm chủ thời gian và phương pháp tự học ở môi trường mới, thực hành lòng biết ơn thầy cô – cha mẹ – bạn bè, tham gia phục vụ cộng đồng và tự tin bước vào Lớp 6',
        ['Chuẩn bị tâm thế trước thay đổi học đường khi chuyển cấp lên Lớp 6', 'Năng lực tự học, ghi chép khoa học và chủ động tìm kiếm hỗ trợ khi cần', 'Thực hành lòng biết ơn, trách nhiệm công dân nhỏ và tình nguyện cộng đồng'],
        [
            _q(12, 1, 'basic', 'Khi bước sang trường Trung học Cơ sở (Lớp 6), điểm thay đổi lớn nhất trong việc học so với Tiểu học mà học sinh Lớp 5 cần chuẩn bị tâm thế sẵn sàng là gì?',
               'Có nhiều thầy cô dạy riêng từng môn, kiến thức sâu rộng hơn và đòi hỏi học sinh tính tự giác – tự quản lí thời gian học tập cao hơn hẳn',
               ['Tất cả mọi môn từ Toán, Ngữ văn đến Âm nhạc đều chỉ do một cô giáo dạy suốt năm', 'Không bao giờ phải làm bài tập hay tự ghi chép bài vào vở nữa', 'Thời gian học ít đi chỉ còn 1 tiếng mỗi tuần'],
               'Hiểu trước những đổi mới ở bậc THCS giúp em háo hức thích nghi nhanh thay vì bỡ ngỡ lo lắng đầu năm Lớp 6.', 'Chuẩn bị tâm thế trước đổi mới môi trường Lớp 6'),
            _q(12, 2, 'basic', 'Thói quen học tập nào giúp học sinh Lớp 5 tự chủ tốt nhất khi tiếp nhận lượng kiến thức nhiều hơn ở bậc Trung học Cơ sở?',
               'Đọc trước bài mới ở nhà 10 phút, tự tóm tắt ý chính bằng sơ đồ tư duy gọn đẹp và ôn lại ngay trong ngày sau giờ học',
               ['Đợi sát ngày kiểm tra học kì mới mở cặp ra xem mình học môn gì', 'Chép nguyên văn không sót một dấu chấm mà không cần hiểu ý nghĩa', 'Giấu kín những bài chưa hiểu vì ngại hỏi thầy cô hoặc bạn giỏi'],
               'Sơ đồ tư duy và thói quen tự hỏi "Hôm nay mình học được ý cốt lõi gì?" biến người học thụ động thành người làm chủ tri thức.', 'Phương pháp tự học sơ đồ tư duy và chuẩn bị bài'),
            _q(12, 3, 'basic', 'Vào những ngày cuối cấp Tiểu học sắp chia tay mái trường gắn bó 5 năm, hành động đẹp nhất thể hiện lòng biết ơn sâu sắc với thầy cô và nhà trường là gì?',
               'Chăm chỉ học rèn luyện thật tốt, viết thiệp hoặc lời tri ân chân thành mộc mạc tặng thầy cô và giữ gìn bàn ghế phòng học sạch đẹp cho khóa em lớp sau',
               ['Vẽ bậy khắc tên đầy mặt bàn học gỗ làm "kỉ niệm chia tay"', 'Tụ tập xé vở giấy vụn ném tung khắp sân trường ngày bế giảng', 'Chờ mua món quà thật đắt tiền mới thể hiện được lòng biết ơn'],
               'Sự trưởng thành ngoan ngoãn, tiến bộ mỗi ngày của học sinh chính là món quà tri ân lớn nhất trong trái tim mỗi người thầy.', 'Tri ân thầy cô và giữ gìn trường lớp sạch đẹp'),
            _q(12, 4, 'basic', 'Quan sát bảng Hành trang Lên Lớp 6 dưới đây. Trong hoạt động phục vụ cộng đồng phù hợp tuổi học sinh cuối tiểu học, việc nào vừa thiết thực vừa giúp em trưởng thành hơn?',
               'Tham gia dọn vệ sinh khu phố, hướng dẫn các em lớp dưới giữ an toàn trường học hoặc quyên góp sách truyện lập tủ sách cộng đồng',
               ['Đứng khoanh tay chờ mọi người phục vụ hết cho riêng mình', 'Phóng xe đạp nhanh gây mất trật tự trước cổng bệnh viện', 'Chỉ đóng góp bằng cách bình luận chê bai việc người khác làm'],
               'Cống hiến vừa sức cho tập thể mở rộng trái tim nhân ái và rèn bản lĩnh giao tiếp xã hội chững chạc.', 'Hoạt động cộng đồng xây dựng trách nhiệm công dân nhỏ',
               fig=table_fig('Hành trang Lên Lớp 6', ['Năng lực cốt lõi', 'Thói quen cần rèn'], [['Tự chủ học tập', 'Sơ đồ tư duy, ôn'], ['Quản lí thời gian', 'Đặt lịch, đúng giờ'], ['Giao tiếp hòa đồng', 'Kết bạn thân thiện'], ['Vì cộng đồng', 'Biết ơn, sống xanh']])),
            _q(12, 5, 'basic', 'Nếu sang môi trường Lớp 6 mới có nhiều bạn đến từ các trường tiểu học khác nhau nên ban đầu chưa quen ai, em nên mở lòng kết bạn thế nào?',
               'Giữ nụ cười thân thiện, chủ động hỏi tên sở thích bạn ngồi cạnh, sẵn sàng chia sẻ giúp đỡ nhỏ và tham gia câu lạc bộ năng khiếu ở trường mới',
               ['Ngồi khoanh tay im lặng một góc tự nhủ không thèm nói chuyện với bạn trường khác', 'Chỉ chơi đúng một nhóm hai bạn cũ và cô lập các bạn mới chuyển tới', 'Khoe khoang điểm số thật to để dọa các bạn mới'],
               'Mỗi người bạn mới mang tới một góc nhìn và thế giới thú vị riêng; sự chân thành dễ mến là chìa khóa mở mọi tình bạn đẹp.', 'Chủ động kết bạn thân thiện ở môi trường mới'),
            _q(12, 6, 'basic', 'Trong buổi lễ tổng kết cuối năm hoặc hành trình lớn lên mỗi ngày, người đầu tiên và âm thầm nhất luôn dõi theo ủng hộ ta suốt 5 năm tiểu học để ta nói lời "Con cảm ơn" chân thành nhất là ai?',
               'Bố mẹ và ông bà – những người chăm sóc từng bữa ăn, giấc ngủ, dạy dỗ phép lịch sự và luôn đứng sau che chở mọi bước đi của em',
               ['Chỉ có người bán đồ chơi ở trước cổng trường', 'Chỉ có những tài khoản mạng xã hội xa lạ chưa từng gặp mặt', 'Không cần cảm ơn bất kì người thân nào trong gia đình'],
               'Lòng hiếu thảo và biết ơn gia đình là gốc rễ vững chắc nhất nâng đỡ bước chân học sinh đi thật xa.', 'Thực hành lòng biết ơn cha mẹ và gia đình'),
            _q(12, 7, 'application', 'Vào tuần đầu tiên học Lớp 6 sắp tới, có môn học mới hơi khó nên dù nghe giảng ở lớp em vẫn thấy lúng túng chưa hiểu kĩ hai phần cuối bài. Cách xử lí chủ động đúng nhất là gì?',
               'Ghi chú cụ thể câu hỏi phần mình chưa rõ rồi mạnh dạn xin phép gặp hỏi thầy cô bộ môn sau giờ học (hoặc trao đổi cùng nhóm bạn học tốt để hiểu tận gốc)',
               ['Giấu kín luôn sự lúng túng đó vì sợ hỏi sẽ bị bạn bè chê là học chậm', 'Bỏ luôn môn học đó từ tuần thứ hai không thèm làm bài nữa', 'Chép bừa bài giải trên mạng nộp đối phó cho xong chuyện'],
               'Học sinh giỏi không phải người biết sẵn mọi thứ, mà là người dám đặt câu hỏi đúng lúc khi chưa hiểu.', 'Chủ động đặt câu hỏi giải đáp khúc mắc bài học'),
            _q(12, 8, 'application', 'Thấy một em học sinh Lớp 1 đứng khóc thút thít vì bị lạc lớp ở hành lang trường tiểu học vào buổi sáng đầu tuần bỡ ngỡ, với tư cách anh chị lớn Lớp 5 gương mẫu, em làm gì?',
               'Cúi xuống mỉm cười nhẹ nhàng trấn an em bé đừng sợ, hỏi tên lớp hoặc xem phù hiệu áo rồi dắt tay đưa em về tận cửa lớp giao cho cô giáo chủ nhiệm',
               ['Cười phá lên trêu em bé mít ướt rồi chạy biến đi mất', 'Chỉ đại một phòng học tầng 4 xa tít bảo em tự đi bộ lên tìm', 'Mặc kệ vì đó không phải em ruột của mình'],
               'Sự dịu dàng che chở các em nhỏ làm đẹp truyền thống văn hóa "Anh chị lớn gương mẫu" dưới mái trường tiểu học.', 'Thể hiện tinh thần anh chị lớn gương mẫu giúp em nhỏ'),
            _q(12, 9, 'application', 'Để giữ tinh thần "Nói không với rác thải và bạo lực" lan tỏa lâu dài ngay từ mùa hè chuyển cấp, một nhóm 5 bạn Lớp 5 định lập dự án cộng đồng nhỏ trong 1 tháng nghỉ hè. Ý tưởng nào vừa sức, an toàn và ý nghĩa nhất?',
               'Dự án "Đổi giấy vụn lấy cây xanh & Đọc sách hè cùng em nhỏ" ngay tại nhà văn hóa tổ dân phố với sự hỗ trợ giám sát của phụ huynh',
               ['Dự án tự tổ chức đua xe đạp phóng thật nhanh trên đường quốc lộ ban đêm', 'Dự án chế tạo pháo tự chế từ diêm và hóa chất mua trên mạng', 'Dự án ngồi xem tivi liên tục 14 tiếng mỗi ngày để ghi nhật kí'],
               'Dự án cộng đồng có phụ huynh đồng hành gắn kết tình bạn mùa hè vừa nuôi dưỡng lòng nhân ái vừa an toàn tuyệt đối.', 'Thiết kế dự án cộng đồng mùa hè an toàn ý nghĩa'),
            _q(12, 10, 'application', 'Quan sát biểu đồ mức độ tự đánh giá sự sẵn sàng về các kĩ năng sống của học sinh cuối Lớp 5 trước ngưỡng cửa chuyển cấp. Điểm sáng lớn nhất và kĩ năng vẫn cần tiếp tục rèn luyện thêm là gì?',
               'Ý thức tuân thủ an toàn – sống xanh đạt rất cao (88% và 85%), còn "Tự chủ học tập & kiểm soát màn hình" (62%) cần tiếp tục rèn bền bỉ',
               ['Học sinh Lớp 5 không hề biết bất kì kĩ năng sống nào (tất cả dưới 10%)', 'Kĩ năng ứng xử văn minh đạt 0%', 'Quản lí thời gian đã hoàn hảo 100% không cần rèn thêm ở Lớp 6'],
               'Tự soi chiếu bản thân giúp em thấy rõ thế mạnh tự hào và điểm cần tiếp tục hoàn thiện khi bước sang chặng đường mới.', 'Tự đánh giá hành trang kĩ năng cuối cấp Tiểu học',
               fig=bars_fig('Tự đánh giá Hành trang Lớp 5 (%)', ['An toàn, tự bảo vệ', 'Sống xanh, tiết kiệm', 'Giao tiếp, hợp tác nhóm', 'Tự chủ học & màn hình'], [88, 85, 79, 62])),
            _q(12, 11, 'application', 'Khi được cô giáo giao nhiệm vụ giữ một vai trò trách nhiệm nhỏ trong lớp (như Quản ca, Phụ trách góc Thư viện xanh hay Cờ đỏ hỗ trợ các bạn), thái độ làm việc chuẩn mực của em là gì?',
               'Thực hiện công việc công tâm, nhẹ nhàng giúp đỡ bạn bè tiến bộ và luôn làm gương chấp hành nội quy trước khi nhắc nhở người khác',
               ['Lợi dụng chức vụ nhỏ để dọa nạt bạn bè hoặc bao che lỗi sai cho bạn thân', 'Chống tay đứng chỉ đạo quát tháo các bạn còn mình không đụng tay việc nào', 'Làm việc qua loa hai ngày đầu rồi bỏ mặc luôn cả học kì'],
               'Trách nhiệm phục vụ tập thể bằng sự gương mẫu và công bằng xây dựng uy tín đẹp từ trái tim bạn bè.', 'Phong cách gương mẫu công tâm khi nhận nhiệm vụ lớp'),
            _q(12, 12, 'application', 'Một người bạn thân lâu năm sắp phải chuyển nhà sang thành phố khác sinh sống ngay sau khi kết thúc Lớp 5 khiến cả hai rất buồn. Cách giữ tình bạn đẹp vượt khoảng cách địa lí là gì?',
               'Trao tặng nhau cuốn sổ lưu bút kỉ niệm đẹp, chúc nhau tự tin ở trường mới và hẹn giữ liên lạc thăm hỏi nhau lành mạnh qua điện thoại của bố mẹ mỗi tháng',
               ['Cắt đứt liên lạc giận hờn bạn vì bạn dám chuyển nhà đi nơi khác', 'Khóc lóc đòi bỏ học đi theo bạn sang thành phố mới', 'Quên sạch ngay mọi kỉ niệm tốt đẹp đã có cùng nhau'],
               'Những kỉ niệm đẹp và sự động viên chân thành giữ tình bạn tuổi thơ bền chặt qua năm tháng.', 'Giữ gìn tình bạn đẹp khi chia tay chuyển trường'),
            _q(12, 13, 'advanced', 'Nhiều người nghĩ "Chăm học giỏi Toán – Văn là đủ làm người thành công rồi, mấy kĩ năng giao tiếp, an toàn hay sống xanh học sau cũng được!". Theo em, vì sao kiến thức học thuật và kĩ năng lối sống phải song hành như hai cánh chim?',
               'Tri thức giúp ta giải quyết bài toán nghề nghiệp, còn kĩ năng sống giữ ta an toàn khỏe mạnh, hợp tác hạnh phúc với mọi người và sống có trách nhiệm với Trái Đất',
               ['Vì kĩ năng sống tự động xuất hiện ngay trong đầu khi giải xong một bài toán nhân', 'Vì học sinh có kĩ năng sống tốt thì không cần biết đọc chữ hay làm toán nữa', 'Vì chỉ cần điểm 10 trên giấy là đủ không bao giờ cần kết bạn với ai'],
               '"Học để biết – Học để làm – Học để chung sống – Học để tự khẳng định mình" là bốn trụ cột giáo dục UNESCO thế kỉ 21.', 'Mối quan hệ hai cánh chim: Tri thức và Kĩ năng sống'),
            _q(12, 14, 'advanced', 'Nếu phải đúc kết phương châm "Công dân Nhỏ Thế kỉ 21" từ toàn bộ hành trình môn Lối sống Lớp 4–5 vào ba phẩm chất cốt lõi, em chọn bộ ba giá trị nào?',
               'An toàn Tự chủ (biết tự bảo vệ chăm sóc mình) – Nhân ái Văn minh (lễ phép, hợp tác, không bạo lực) – Sống Xanh Trách nhiệm (tiết kiệm, bảo vệ hành tinh)',
               ['Nóng nảy Bốc đồng – Thờ ơ Vô cảm – Lãng phí Tài nguyên', 'Làm hộ 100% – Nói trống không – Chỉ biết riêng mình', 'Sợ hãi Rụt rè – Bắt chước Mù quáng – Xả rác Bừa bãi'],
               'An toàn Tự chủ, Nhân ái Văn minh và Sống Xanh Trách nhiệm là tấm hộ chiếu đẹp nhất đưa em tự tin bước vào Trung học Cơ sở.', 'Ba phẩm chất cốt lõi Công dân Nhỏ Thế kỉ 21'),
            _q(12, 15, 'advanced', 'Khi đứng trước cổng trường Trung học Cơ sở mới vào ngày khai giảng Lớp 6 tới, điều gì giúp một học sinh bước qua cánh cổng ấy với nụ cười vững vàng thay vì lo sợ?',
               'Niềm tin vào nền tảng kiến thức cùng kho kĩ năng tự lập, giao tiếp, cảm xúc và an toàn đã rèn suốt 5 năm Tiểu học – sẵn sàng học điều mới',
               ['Mang theo thật nhiều đồ chơi đắt tiền để khoe với mọi người', 'Hứa rằng sẽ không bao giờ giơ tay phát biểu hay kết bạn với ai mới', 'Tin rằng lên Lớp 6 sẽ không còn bất kì thử thách nào cần cố gắng nữa'],
               'Hành trang vững vàng nhất không nằm trong chiếc cặp nặng sách mà nằm trong bản lĩnh tự tin và trái tim tử tế của chính em.', 'Tự tin bước qua ngưỡng cửa Trung học Cơ sở'),
        ]
    ))

    return lessons
